function hexToRgb(hex) {
  const r = parseInt(hex.substr(1, 2), 16);
  const g = parseInt(hex.substr(3, 2), 16);
  const b = parseInt(hex.substr(5, 2), 16);
  return "rgb(" + r + "," + g + "," + b + ")";
}

function winner(rules) {
  function rank(sel) {
    if (sel === "inline") return 4;
    if (sel[0] === "#") return 3;
    if (sel[0] === ".") return 2;
    return 1;
  }
  let best = null;
  for (const r of rules) {
    if (best === null || rank(r.sel) >= rank(best.sel)) best = r;
  }
  return best.value;
}

