function countFizzBuzz(n) {
  let c = 0;
  for (let i = 1; i <= n; i++) {
    if (i % 3 == 0 && i % 5 == 0) {
      c++;
    }
  }
  return c;
}

function findIndex(arr, target) {
  let found = false;
  let i = 0;
  while (!found && i < arr.length) {
    if (arr[i] == target) {
      found = true;
    } else {
      i++;
    }
  }
  return found ? i : -1;
}

