def dest_port(url):
    defaults = {'http': 80, 'https': 443, 'ftp': 21}
    scheme, rest = url.split('://', 1)
    host = rest.split('/', 1)[0]
    if ':' in host:
        return int(host.split(':')[1])
    return defaults[scheme]

